class BaseAnimal:
	extends RefCounted
	func speak() -> String:
		return "..."

class Dog:
	extends BaseAnimal
	func speak() -> String:
		return "Bau!"

func run() -> String:
	var pet: BaseAnimal = Dog.new()
	return pet.speak()

class Weapon:
	extends RefCounted
	var damage: int = 10
	func calculate_damage() -> int:
		return damage

class MagicWeapon:
	extends Weapon
	var bonus: int = 5
	func calculate_damage() -> int:
		return super() + bonus

func run() -> int:
	var mw := MagicWeapon.new()
	return mw.calculate_damage()

class Entity:
	extends RefCounted

class Player:
	extends Entity

class Enemy:
	extends Entity

func run() -> bool:
	var p: Entity = Player.new()
	return p is Entity and not (p is Enemy)

class Box:
	extends RefCounted
	var value: int = 100

class MagicBox:
	extends Box
	var secret: int = 42

func run() -> int:
	var normal_box: Box = Box.new()
	var as_magic: MagicBox = normal_box as MagicBox
	if as_magic == null:
		return 0
	return as_magic.secret

class Multiplier:
	extends RefCounted
	var factor: int = 2
	func apply(x: int) -> int:
		return x * factor

class TripleMultiplier:
	extends Multiplier
	func _init() -> void:
		factor = 3

func run() -> int:
	var list: Array[Multiplier] = [Multiplier.new(), TripleMultiplier.new()]
	var total: int = 0
	for m in list:
		total += m.apply(10)
	return total
